"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/popover.css";
import { Popover as PopoverPrimitive } from "@base-ui/react/popover";
import { cn } from "../../lib/cn";

export function Popover(props: PopoverPrimitive.Root.Props) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />;
}

export function PopoverTrigger(props: PopoverPrimitive.Trigger.Props) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />;
}

export type PopoverContentProps = PopoverPrimitive.Popup.Props &
  Pick<PopoverPrimitive.Positioner.Props, "align" | "alignOffset" | "side" | "sideOffset">;

export function PopoverContent({
  className,
  side = "bottom",
  sideOffset = 6,
  align = "start",
  alignOffset = 0,
  ...props
}: PopoverContentProps) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Positioner className="whatiuse-positioner" side={side} sideOffset={sideOffset} align={align} alignOffset={alignOffset}>
        <PopoverPrimitive.Popup className={cn("whatiuse-popover", className)} {...props} data-layer="flyout" />
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Portal>
  );
}

export const PopoverTitle = PopoverPrimitive.Title;
export const PopoverDescription = PopoverPrimitive.Description;

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-positioner { z-index: var(--whatiuse-layer-flyout); }

.whatiuse-popover { width: 278px; padding: 12px; border-radius: var(--whatiuse-radius-overlay); background: var(--whatiuse-bg-flyout); box-shadow: var(--whatiuse-shadow-flyout); outline: 0; transform-origin: var(--transform-origin); transition: opacity var(--whatiuse-flyout-enter-duration) var(--whatiuse-ease-out), transform var(--whatiuse-flyout-enter-duration) var(--whatiuse-ease-out); }

.whatiuse-popover[data-starting-style] { opacity: 0; transform: scale(0.98); }

.whatiuse-popover[data-ending-style] { opacity: 0; transform: scale(0.99); transition-duration: var(--whatiuse-flyout-exit-duration); }

.whatiuse-popover { background: var(--whatiuse-bg-flyout); }

@media (prefers-reduced-motion: reduce) {
.whatiuse-popover {
    transition-property: opacity;
    transition-duration: var(--whatiuse-exit-duration);
  }

.whatiuse-popover[data-starting-style],
.whatiuse-popover[data-ending-style] { transform: none; }
}
}
